mapper.select:
select id,seckill_id,seckill_time_id,sku_id,sku_name,img_url,seckill_price,seckill_stock,seckill_limit,seckill_sale,seckill_sort,create_time,update_time,is_deleted
from seckill_sku

    is_deleted=0

        and seckill_id = #{vo.seckillId}


        and seckill_time_id = #{vo.seckillTimeId}
